#[test_only]
module protocol::emode_test {

  use sui::test_scenario;
  use sui::clock;

  use protocol::market_t::MainMarket;
  use protocol::market::lending_default_emode_group;
  use test_coin::eth::ETH;
  use test_coin::usdc::USDC;
  use test_coin::usdt::USDT;

  const ADMIN: address = @0xAD;

  #[test]
  public fun test_create_new_emode_group() {
    // Test creating a new emode group
    let mut scenario_value = test_scenario::begin(ADMIN);
    let scenario = &mut scenario_value;
    let mut clock = clock::create_for_testing(scenario.ctx());

    let (admin_cap, app, mut market, coin_registry) = protocol::app_t::default_app_init<MainMarket>(
        scenario,
        &mut clock,
        ADMIN,
    );

    // Create a new emode group
    protocol::emode_admin::onboard_new_emode_group<MainMarket>(
        &admin_cap,
        &app,
        &mut market,
        0,
        &clock,
        scenario.ctx(),
    );

    // Verify that a new group was created (should be group ID 1, since 0 is default)
    let registry = market.emode_registry();
    registry.ensure_group_exists(1);

    clock::destroy_for_testing(clock);

    test_scenario::return_shared(market);

    std::unit_test::destroy(admin_cap);
    std::unit_test::destroy(app);
    std::unit_test::destroy(coin_registry);
    test_scenario::end(scenario_value);
  }

  #[test]
  public fun test_onboard_asset_to_emode_group() {
    // Test onboarding an asset to an emode group with specific parameters
    let mut scenario_value = test_scenario::begin(ADMIN);
    let scenario = &mut scenario_value;
    let mut clock = clock::create_for_testing(scenario.ctx());

    let (admin_cap, app, mut market, coin_registry) = protocol::app_t::default_app_init<MainMarket>(
        scenario,
        &mut clock,
        ADMIN,
    );

    // Create a new emode group
    protocol::emode_admin::onboard_new_emode_group<MainMarket>(
        &admin_cap,
        &app,
        &mut market,
        0,
        &clock,
        scenario.ctx(),
    );

    // Create limiter parameters
    let deposit_limiter = protocol::emode_admin::create_limiter(
        &admin_cap,
        &app,
        5000000000, // 5B limit
        86400,      // 24 hours cycle
        3600,       // 1 hour segments
    );

    let borrow_limiter = protocol::emode_admin::create_limiter(
        &admin_cap,
        &app,
        2000000000, // 2B limit
        86400,      // 24 hours cycle
        3600,       // 1 hour segments
    );

    // Create emode params for ETH with specific parameters
    let emode_params = protocol::emode_admin::create_emode_params_test(
        &admin_cap,
        8000,  // 80% collateral factor in BPS
        8500,  // 85% liquidation factor in BPS
        500,   // 5% liquidation incentive in BPS
        1000000000, // max borrow amount: 1B
        11000, // 110% borrow weight in BPS
        10,    // 0.1% flash loan fee rate in BPS
        deposit_limiter,
        borrow_limiter,
    );

    // Onboard ETH to the new emode group (group 1)
    protocol::emode_admin::onboard_asset_to_emode_group<MainMarket, ETH>(
        &admin_cap,
        &app,
        &mut market,
        1, // group ID
        emode_params,
        scenario.ctx(),
    );

    // Verify that ETH is supported in group 1
    let registry = market.emode_registry();
    let eth_type = std::type_name::with_defining_ids<ETH>();
    assert!(registry.is_support(1, eth_type), 0);

    // Verify the emode parameters are correct
    let emode = registry.borrow_emode_group(1).borrow_emode(eth_type);

    let collateral = emode.collateral();
    assert!(collateral.collateral_factor().eq(math::float::from_quotient(8000, 10000)), 1);
    assert!(collateral.liquidation_factor().eq(math::float::from_quotient(8500, 10000)), 2);
    assert!(collateral.liquidation_incentive().eq(math::float::from_quotient(500, 10000)), 3);

    let borrow = emode.borrow();
    assert!(borrow.max_borrow_amount() == 1000000000, 4);
    assert!(borrow.borrow_weight().eq(math::float::from_quotient(11000, 10000)), 5);

    let flashloan = emode.flash_loan();
    assert!(flashloan.fee_rate().eq(math::float::from_quotient(10, 10000)), 6);

    clock::destroy_for_testing(clock);

    test_scenario::return_shared(market);

    std::unit_test::destroy(admin_cap);
    std::unit_test::destroy(app);
    std::unit_test::destroy(coin_registry);
    test_scenario::end(scenario_value);
  }

  #[test]
  public fun test_multiple_assets_different_groups() {
    // Test that different assets in different groups have different parameters
